const {chromium}=require('playwright'),fs=require('fs'),assert=require('node:assert/strict');
(async()=>{const b=await chromium.launch({headless:true});try{const p=await b.newPage({viewport:{width:390,height:844}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.setContent('<main></main>');for(const name of ['00-core','05-primitives','48-chat'])await p.addStyleTag({content:fs.readFileSync('server/web/css/'+name+'.css','utf8')});await p.evaluate(()=>{window.el=(tag,cls,text)=>{const e=document.createElement(tag);e.className=cls||'';e.textContent=text||'';return e};window.calls=[];window.refreshes=0;window.fail=true;window.postJSONOk=async(url,body)=>{calls.push({url,body});if(fail)throw Error('offline');return {delivery:{stopRequested:true}}};window.session={id:'session-one',deliveries:[{id:'active-one',state:'running'},{id:'queued-one',state:'queued',text:'Exact pending instruction'}]};});const source=fs.readFileSync('server/web/js/48-chat.js','utf8');await p.addScriptTag({content:source.slice(source.indexOf('function chatNativeInterruptionControls('))});await p.evaluate(()=>document.querySelector('main').append(chatNativeInterruptionControls(session,'/api/agents/chat/alfred/sessions',()=>refreshes++)));const button=p.getByRole('button',{name:'Interrupt turn and cancel 1 queued',exact:true});await button.click();await p.getByRole('status').filter({hasText:'offline'}).waitFor();assert.equal(await button.isEnabled(),true);assert.equal(await p.evaluate(()=>refreshes),0);await p.evaluate(()=>fail=false);await button.click();assert.equal(await button.isDisabled(),true);assert.equal(await p.evaluate(()=>refreshes),1);assert.deepEqual(await p.evaluate(()=>calls),[1,2].map(()=>({url:'/api/agents/chat/alfred/sessions/session-one/interrupt',body:{requestId:'active-one'}})));await p.evaluate(()=>{session.deliveries[0].stopRequested=true;session.deliveries[1].state='cancelled';document.querySelector('main').replaceChildren(chatNativeInterruptionControls(session,'base',()=>{}))});await p.getByText('Interruption requested; waiting for the runner to return.',{exact:true}).waitFor();assert.equal(await p.getByRole('button',{name:'Interrupt turn',exact:true}).isDisabled(),true);await p.getByText('Cancelled before dispatch',{exact:true}).click();await p.getByText('Exact pending instruction',{exact:true}).waitFor();await p.evaluate(()=>{session.deliveries[0].state='interrupted';document.querySelector('main').replaceChildren(chatNativeInterruptionControls(session,'base',()=>{}))});assert.equal(await p.getByRole('button').count(),0);for(const width of [320,390,1440]){await p.setViewportSize({width,height:844});assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true)}await p.setViewportSize({width:390,height:844});await p.screenshot({path:'/tmp/manifest-native-interrupt-phone.png'});assert.deepEqual(errors,[]);console.log('PASS: explicit targeted interrupt, failure retry, waiting state and retained cancelled text');}finally{await b.close()}})().catch(e=>{console.error(e);process.exitCode=1});
